@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Nunito:wght@500;600;700;800;900&display=swap');
:root{--ink:#f7f4df;--deep:#193c2d;--gold:#ffdf91;--panel:rgba(24,56,42,.88);--pixel-shadow:0 4px 0 rgba(12,35,27,.56),0 8px 20px rgba(17,42,30,.19)}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
