.game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#75a957;isolation:isolate}
#game{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;z-index:-1}
.topbar{position:absolute;z-index:2;top:max(18px,env(safe-area-inset-top));left:clamp(16px,3vw,42px);right:clamp(16px,3vw,42px);display:flex;align-items:center;justify-content:space-between;pointer-events:none}
.brand-mark{display:flex;align-items:center;gap:11px;text-shadow:0 2px 6px #173a2d8c}.brand-mark strong{font-size:13px;letter-spacing:.18em;display:block;font-weight:900}.brand-mark small{font:9px 'DM Mono',monospace;letter-spacing:.17em;color:#e5efbd;display:block;margin-top:3px}.brand-sun{display:grid;place-items:center;width:37px;height:37px;border:1px solid #fff3c879;border-radius:11px;background:#325c3dad;color:#ffe9a8;font-size:19px;box-shadow:0 3px 12px #163c2a42}
.day-pill{height:34px;display:flex;align-items:center;gap:9px;padding:0 12px;border:1px solid #f1f3ca52;border-radius:20px;background:#214530b8;backdrop-filter:blur(8px);font:10px 'DM Mono',monospace;letter-spacing:.06em;color:#f2f0d7;box-shadow:0 3px 12px #1738212e}.day-pill i{height:13px;width:1px;background:#f1f3ca5a}.sun-icon{font-size:13px;color:#ffe39c}.sound-button{pointer-events:auto;border:1px solid #e8f0cf69;background:#244934b5;color:#f6f1d7;border-radius:50%;width:36px;height:36px;font-size:17px;cursor:pointer;box-shadow:0 3px 12px #1738212e}
.quest-card{position:absolute;top:88px;left:clamp(16px,3vw,42px);width:min(284px,calc(100vw - 32px));padding:15px 16px 13px;background:var(--panel);border:1px solid #edebc75c;border-radius:5px 13px 13px 13px;box-shadow:var(--pixel-shadow);backdrop-filter:blur(9px);color:#f7f4df;z-index:2}.quest-heading{display:flex;align-items:center;gap:10px}.quest-pin{height:31px;width:31px;display:grid;place-items:center;border:1px solid #e6d99470;background:#e6d99418;color:#f4dc8c;border-radius:8px;font-size:17px}.quest-heading small{font:8px 'DM Mono',monospace;letter-spacing:.14em;color:#c3d6a5}.quest-heading h1{font-size:15px;margin:2px 0 0;font-weight:800;letter-spacing:.01em}.quest-card p{color:#e0e9ce;font-size:11px;line-height:1.45;margin:10px 0 11px}.quest-progress{display:flex;align-items:center;gap:9px}.progress-track{height:5px;background:#0f2c20a6;border-radius:4px;overflow:hidden;flex:1}.progress-track span{height:100%;width:0;display:block;background:#f3d982;border-radius:4px;transition:width .3s ease}.quest-progress b{font:9px 'DM Mono',monospace;color:#f5e5ad;min-width:30px;text-align:right}
.location-tag{position:absolute;top:30px;left:50%;transform:translateX(-50%);z-index:1;display:flex;align-items:center;gap:7px;padding:8px 12px;background:#1a3e2baa;border:1px solid #f1f2c04c;border-radius:4px;color:#f7f1cf;font:9px 'DM Mono',monospace;letter-spacing:.1em;white-space:nowrap;box-shadow:0 3px 12px #1738212e}.location-dot{width:6px;height:6px;border-radius:50%;background:#dfd78f;box-shadow:0 0 7px #f1e694}.tag-divider{color:#a7bb91;margin:0 1px}.toast{position:absolute;z-index:3;top:38%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.25s;pointer-events:none;padding:10px 17px;border-radius:4px;background:#183c2de8;border:1px solid #f6e8aa84;box-shadow:var(--pixel-shadow);font-size:12px;font-weight:800;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}
.bottom-ui{position:absolute;z-index:2;left:clamp(16px,3vw,42px);right:clamp(16px,3vw,42px);bottom:max(20px,env(safe-area-inset-bottom));display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.hint-pill{display:flex;align-items:center;gap:9px;padding:8px 12px 8px 8px;border:1px solid #edf2ce60;border-radius:4px 12px 12px 12px;background:#1b412fc7;box-shadow:0 4px 12px #17382131;backdrop-filter:blur(8px);font-size:11px;font-weight:700;color:#eff0d8;min-height:36px;transition:opacity .2s}.hint-key{display:grid;place-items:center;width:21px;height:21px;background:#f1d889;color:#31452c;border-radius:5px;font:700 11px 'DM Mono',monospace;box-shadow:0 2px 0 #bda957}.control-note{display:flex;align-items:center;gap:6px;color:#fff4d8b8;text-shadow:0 1px 5px #163c2d;font:9px 'DM Mono',monospace;letter-spacing:.04em;margin-bottom:8px}.control-note kbd{padding:4px 5px;border:1px solid #f1f1d65c;border-radius:4px;background:#254b35a8;color:#fff6da;font:9px 'DM Mono',monospace}.note-separator{opacity:.6;margin:0 3px}.mobile-controls{display:none;pointer-events:auto;align-items:flex-end;gap:26px}.dpad{position:relative;width:120px;height:120px;display:grid;grid-template:repeat(3,1fr)/repeat(3,1fr);filter:drop-shadow(0 3px 3px #183a2c5e)}.dpad-btn{border:1px solid #f7f1cf70;background:#244b37c9;color:#fff5d5;font-size:15px;touch-action:none;display:grid;place-items:center;padding:0}.dpad-btn:active,.dpad-btn.pressed{background:#d7c67a;color:#28432f}.dpad-btn.up{grid-area:1/2;border-radius:8px 8px 2px 2px}.dpad-btn.left{grid-area:2/1;border-radius:8px 2px 2px 8px}.dpad-btn.down{grid-area:3/2;border-radius:2px 2px 8px 8px}.dpad-btn.right{grid-area:2/3;border-radius:2px 8px 8px 2px}.dpad-center{grid-area:2/2;background:#244b37c9;border-top:1px solid #f7f1cf70;border-bottom:1px solid #f7f1cf70}.action-button{width:64px;height:64px;border-radius:50%;border:2px solid #fff1bd;background:#d8b95f;color:#3b4b30;box-shadow:0 4px 0 #927e45,0 6px 12px #193a2b77;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;touch-action:none}.action-button:active{transform:translateY(3px);box-shadow:0 1px 0 #927e45}.action-button span{font:900 20px 'Nunito',sans-serif;line-height:20px}.action-button small{font:8px 'DM Mono',monospace;letter-spacing:.12em}
.dialogue-wrap{position:absolute;z-index:5;inset:0;display:flex;align-items:flex-end;justify-content:center;padding:24px clamp(16px,7vw,100px) max(30px,env(safe-area-inset-bottom));background:linear-gradient(0deg,#102c2480,transparent 58%);opacity:0;pointer-events:none;transition:opacity .2s}.dialogue-wrap.open{opacity:1;pointer-events:auto}.dialogue-box{position:relative;width:min(760px,100%);min-height:132px;padding:28px 28px 24px;background:#f2e7bf;border:3px solid #fff2ca;border-radius:4px 15px 15px 15px;box-shadow:0 5px 0 #665b38,0 10px 30px #152b1d77;color:#344a35}.dialogue-box:before{content:'';position:absolute;inset:5px;border:1px solid #96855480;border-radius:2px 10px 10px 10px;pointer-events:none}.speaker-badge{position:absolute;top:-15px;left:18px;padding:6px 13px;background:#345a3c;border:2px solid #fbefc7;border-radius:4px;color:#fff1c7;font:10px 'DM Mono',monospace;letter-spacing:.13em;box-shadow:0 2px 0 #536341}.dialogue-box p{position:relative;margin:0;max-width:90%;font-size:15px;line-height:1.6;font-weight:700}.dialogue-next{position:absolute;right:20px;bottom:15px;border:0;background:none;color:#526746;font-size:17px;animation:bob .8s infinite alternate}.dialogue-help{position:absolute;right:43px;bottom:20px;font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#777650}.vignette{position:absolute;z-index:0;inset:0;pointer-events:none;box-shadow:inset 0 0 100px #18372820}
@keyframes bob{to{transform:translateY(4px)}}
@media (pointer:coarse),(max-width:760px){.mobile-controls{display:flex}.control-note{display:none}.bottom-ui{bottom:max(18px,env(safe-area-inset-bottom));}.hint-pill{align-self:flex-start;margin-bottom:94px}.quest-card{top:78px;width:min(250px,calc(100vw - 32px));padding:12px 13px}.quest-card p{font-size:10px;margin:8px 0}.quest-heading h1{font-size:14px}.location-tag{top:25px;font-size:8px}.topbar{top:max(15px,env(safe-area-inset-top))}.brand-mark strong{font-size:11px}.brand-mark small{font-size:8px}.brand-sun{width:32px;height:32px}.day-pill{font-size:9px;height:30px;gap:7px;padding:0 9px}.sound-button{width:32px;height:32px}.dialogue-wrap{padding-bottom:max(194px,calc(env(safe-area-inset-bottom) + 180px));padding-left:16px;padding-right:16px}.dialogue-box{padding:25px 20px 24px;min-height:132px}.dialogue-box p{font-size:13px}}
@media (max-width:380px){.dpad{width:102px;height:102px}.mobile-controls{gap:18px}.action-button{width:58px;height:58px}.quest-card{width:220px}.day-pill{gap:5px}.brand-mark{gap:7px}}
@media (min-width:761px) and (pointer:fine){.bottom-ui{bottom:24px}.hint-pill{margin-bottom:0}}

(() => {
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const T = 16, WORLD = 80;
  const questTitle = document.querySelector('#questTitle');
  const questText = document.querySelector('#questText');
  const progressText = document.querySelector('#progressText');
  const progressFill = document.querySelector('#progressFill');
  const hint = document.querySelector('#hint');
  const toast = document.querySelector('#toast');
  const dialogue = document.querySelector('#dialogue');
  const dialogueText = document.querySelector('#dialogueText');
  const speakerBadge = document.querySelector('#speakerBadge');
  const dialogueNext = document.querySelector('#dialogueNext');
  let width = innerWidth, height = innerHeight, dpr = 1, scale = 1, tileSize = 24;
  let lastTime = 0, elapsed = 0, toastTimer = 0, soundOn = false, audioCtx;
  let phase = 0, petals = 0, dialogueLines = [], dialogueIndex = 0, afterDialogue = null;
  let lastInteract = 0;
  const keys = new Set(), touchDirs = new Set();
  const flowers = [
    { x: 31.5, y: 38.5, found: false, color: '#f5e89c' },
    { x: 40.5, y: 35.5, found: false, color: '#f4c7dc' },
    { x: 43.5, y: 42.5, found: false, color: '#f2e89b' }
  ];
  const mira = { x: 38.5, y: 31.5 };
  const player = { x: 35.5, y: 40.5, facing: 'down', moving: false, step: 0 };
  const obstacles = new Map(), decorations = [];
  const hash = (x, y) => { let n = (x * 374761393 + y * 668265263) | 0; n = Math.imul(n ^ (n >>> 13), 1274126177); return ((n ^ (n >>> 16)) >>> 0) / 4294967295; };
  const pathY = x => 41 + Math.sin(x * .13) * 3.2 + Math.sin(x * .37) * .9;
  const keyOf = (x, y) => `${x},${y}`;
  function isSafeSpot(x, y) {
    if (Math.hypot(x - player.x, y - player.y) < 7 || Math.hypot(x - mira.x, y - mira.y) < 2.4) return true;
    return flowers.some(f => Math.hypot(x - f.x, y - f.y) < 1.5);
  }
  function makeWorld() {
    for (let y = 0; y < WORLD; y++) for (let x = 0; x < WORLD; x++) {
      const edge = Math.min(x, y, WORLD - 1 - x, WORLD - 1 - y);
      const r = hash(x + 170, y + 71);
      const nearPath = Math.abs(y - pathY(x)) < 2.8;
      if (!isSafeSpot(x + .5, y + .5) && !nearPath && (edge < 3 ? r > .34 : r > .991)) {
        obstacles.set(keyOf(x, y), edge < 3 || r > .997 ? 'tree' : (r > .995 ? 'rock' : 'bush'));
      }
      if (hash(x + 83, y + 391) > .76) decorations.push({ x, y, kind: hash(x + 410, y) > .5 ? 'grass' : 'flower', variant: hash(x, y + 808) });
    }
  }
  makeWorld();
  function resize() {
    width = innerWidth; height = innerHeight; dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.round(width * dpr); canvas.height = Math.round(height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    tileSize = Math.min(width / 20, height / 13, 34);
    scale = tileSize / T;
    ctx.imageSmoothingEnabled = false;
  }
  addEventListener('resize', resize); resize();

  function drawGround(tx, ty) {
    const r = hash(tx + 500, ty + 900);
    const pathDist = Math.abs(ty + .5 - pathY(tx + .5));
    let color = r > .52 ? '#77ae59' : (r > .22 ? '#73a854' : '#6fa451');
    if (pathDist < 1.22) color = r > .56 ? '#c9b979' : '#c4b271';
    else if (pathDist < 1.52) color = r > .5 ? '#91b567' : '#83ad5e';
    ctx.fillStyle = color; ctx.fillRect(tx * T, ty * T, T, T);
    if (pathDist < 1.55) {
      ctx.fillStyle = '#d6c78b';
      if (r > .45) ctx.fillRect(tx * T + 3 + Math.floor(r * 7), ty * T + (pathDist < 1.22 ? 5 : 2), 3, 2);
      if (r > .76) ctx.fillRect(tx * T + 11, ty * T + 10, 2, 2);
    } else {
      if (r > .56) { ctx.fillStyle = '#8abb63'; ctx.fillRect(tx * T + (r > .8 ? 11 : 3), ty * T + (r > .8 ? 4 : 11), 2, 2); }
      if (r < .09) { ctx.fillStyle = '#5e944b'; ctx.fillRect(tx * T + 9, ty * T + 2, 2, 2); }
    }
  }
  function drawFlower(x, y, color, size = 1, glow = false) {
    const bob = Math.sin(elapsed * 2.8 + x * 4) * .45;
    const px = x * T, py = y * T + bob;
    if (glow) { ctx.globalAlpha = .24 + (Math.sin(elapsed * 3 + x) + 1) * .09; ctx.fillStyle = '#fff6bd'; ctx.fillRect(px - 5, py - 8, 26, 26); ctx.globalAlpha = 1; }
    ctx.fillStyle = '#447946'; ctx.fillRect(px + 7, py + 7, 2, 6); ctx.fillRect(px + 4, py + 10, 3, 2);
    ctx.fillStyle = color; ctx.fillRect(px + 4, py + 2, 3, 3); ctx.fillRect(px + 9, py + 2, 3, 3); ctx.fillRect(px + 2, py + 5, 3, 3); ctx.fillRect(px + 10, py + 5, 3, 3); ctx.fillRect(px + 5, py + 8, 5, 3);
    ctx.fillStyle = '#f9d675'; ctx.fillRect(px + 6, py + 5, 3, 3);
    if (size > 1) { ctx.fillStyle = '#e9e19d'; ctx.fillRect(px + 13, py + 11, 2, 2); }
  }
  function drawTree(tx, ty, kind = 'tree') {
    const x = tx * T, y = ty * T;
    if (kind === 'rock') {
      ctx.fillStyle = '#55834a'; ctx.fillRect(x + 2, y + 12, 12, 3);
      ctx.fillStyle = '#929b77'; ctx.fillRect(x + 4, y + 7, 9, 6); ctx.fillRect(x + 6, y + 5, 5, 2);
      ctx.fillStyle = '#b7b68d'; ctx.fillRect(x + 6, y + 7, 3, 2); return;
    }
    if (kind === 'bush') {
      ctx.fillStyle = '#4d8145'; ctx.fillRect(x + 2, y + 8, 12, 6); ctx.fillRect(x + 4, y + 5, 8, 8);
      ctx.fillStyle = '#67994d'; ctx.fillRect(x + 4, y + 7, 5, 3); ctx.fillRect(x + 10, y + 9, 3, 2); return;
    }
    ctx.fillStyle = '#4d7441'; ctx.fillRect(x + 5, y + 12, 7, 4);
    ctx.fillStyle = '#735f3c'; ctx.fillRect(x + 7, y + 9, 3, 6); ctx.fillRect(x + 5, y + 13, 7, 2);
    ctx.fillStyle = '#3e7543'; ctx.fillRect(x + 1, y + 6, 14, 7); ctx.fillRect(x + 3, y + 3, 10, 9); ctx.fillRect(x + 5, y + 1, 6, 8);
    ctx.fillStyle = '#568d4b'; ctx.fillRect(x + 4, y + 4, 5, 4); ctx.fillRect(x + 2, y + 7, 4, 3); ctx.fillRect(x + 10, y + 5, 3, 4);
    ctx.fillStyle = '#76a954'; ctx.fillRect(x + 6, y + 3, 3, 2); ctx.fillRect(x + 3, y + 6, 2, 2);
    ctx.fillStyle = '#345f3d'; ctx.fillRect(x + 11, y + 10, 2, 2);
  }
  function drawMira() {
    const x = mira.x * T, y = mira.y * T;
    drawShadow(x, y + 3);
    const wave = Math.sin(elapsed * 3.5) > .35;
    ctx.fillStyle = '#493b34'; ctx.fillRect(x + 4, y - 10, 8, 5); ctx.fillRect(x + 3, y - 7, 10, 5);
    ctx.fillStyle = '#f1c99a'; ctx.fillRect(x + 5, y - 7, 7, 7); ctx.fillStyle = '#6e4b3b'; ctx.fillRect(x + 5, y - 3, 2, 1);
    ctx.fillStyle = '#b75454'; ctx.fillRect(x + 4, y, 9, 8); ctx.fillStyle = '#e87b68'; ctx.fillRect(x + 4, y, 9, 3);
    ctx.fillStyle = '#ecd6a5'; ctx.fillRect(x + 5, y + 7, 3, 4); ctx.fillRect(x + 10, y + 7, 3, 4);
    ctx.fillStyle = '#815444'; ctx.fillRect(x + 4, y + 10, 4, 2); ctx.fillRect(x + 10, y + 10, 4, 2);
    if (phase < 2 && wave) { ctx.fillStyle = '#f1c99a'; ctx.fillRect(x + 13, y - 1, 3, 3); ctx.fillStyle = '#e87b68'; ctx.fillRect(x + 14, y - 3, 2, 3); }
    if (Math.hypot(player.x - mira.x, player.y - mira.y) < 2.2) drawPrompt(x + 8, y - 17, 'A');
  }
  function drawShadow(x, y) { ctx.fillStyle = '#30583975'; ctx.fillRect(x - 1, y, 17, 4); ctx.fillRect(x + 2, y - 1, 11, 6); }
  function drawPlayer() {
    const x = player.x * T, y = player.y * T;
    drawShadow(x, y + 3);
    const walk = player.moving ? Math.floor(player.step / 7) % 2 : 0;
    const bob = player.moving && walk ? -1 : 0;
    const face = player.facing;
    ctx.fillStyle = '#5b4339'; ctx.fillRect(x + 4, y - 10 + bob, 9, 5); ctx.fillRect(x + 3, y - 7 + bob, 10, 4);
    ctx.fillStyle = '#e9bc91'; ctx.fillRect(x + 5, y - 7 + bob, 7, 7);
    if (face !== 'up') { ctx.fillStyle = '#3d493a'; if (face === 'left') ctx.fillRect(x + 5, y - 4 + bob, 2, 2); else if (face === 'right') ctx.fillRect(x + 10, y - 4 + bob, 2, 2); else { ctx.fillRect(x + 6, y - 4 + bob, 1, 2); ctx.fillRect(x + 10, y - 4 + bob, 1, 2); } }
    ctx.fillStyle = '#527b94'; ctx.fillRect(x + 3, y + bob, 11, 8); ctx.fillRect(x + 5, y + 7 + bob, 7, 2);
    ctx.fillStyle = '#e2d18a'; ctx.fillRect(x + 7, y + bob, 3, 6); ctx.fillRect(x + 6, y + 1 + bob, 5, 1);
    ctx.fillStyle = '#e9bc91'; if (face === 'left') ctx.fillRect(x + 1, y + 2 + bob, 3, 4); else if (face === 'right') ctx.fillRect(x + 13, y + 2 + bob, 3, 4);
    ctx.fillStyle = '#51433a'; const legY = y + 8 + bob;
    if (player.moving && walk) { ctx.fillRect(x + 4, legY, 4, 4); ctx.fillRect(x + 10, legY + 1, 4, 3); }
    else { ctx.fillRect(x + 4, legY, 4, 4); ctx.fillRect(x + 10, legY, 4, 4); }
    ctx.fillStyle = '#e0cf9a'; ctx.fillRect(x + 3, y + 11 + bob, 5, 2); ctx.fillRect(x + 10, y + 11 + bob, 5, 2);
  }
  function drawPrompt(x, y, label) {
    ctx.fillStyle = '#fff1b9'; ctx.fillRect(x - 4, y - 4, 16, 13); ctx.fillStyle = '#3b563e'; ctx.fillRect(x - 3, y - 3, 14, 11);
    ctx.fillStyle = '#fff0bd'; ctx.font = 'bold 9px monospace'; ctx.textAlign = 'center'; ctx.fillText(label, x + 4, y + 5);
  }
  function render() {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.fillStyle = '#70a552'; ctx.fillRect(0, 0, width, height);
    ctx.save(); ctx.translate(width / 2 - player.x * tileSize, height / 2 - player.y * tileSize); ctx.scale(scale, scale);
    const minX = Math.floor(player.x - width / tileSize / 2) - 2, maxX = Math.ceil(player.x + width / tileSize / 2) + 2;
    const minY = Math.floor(player.y - height / tileSize / 2) - 2, maxY = Math.ceil(player.y + height / tileSize / 2) + 2;
    for (let y = minY; y <= maxY; y++) for (let x = minX; x <= maxX; x++) {
      if (x < 0 || y < 0 || x >= WORLD || y >= WORLD) { ctx.fillStyle = '#365c3b'; ctx.fillRect(x * T, y * T, T, T); continue; }
      drawGround(x, y);
    }
    for (const d of decorations) if (d.x >= minX && d.x <= maxX && d.y >= minY && d.y <= maxY && !obstacles.has(keyOf(d.x, d.y))) {
      if (d.kind === 'grass') { ctx.fillStyle = d.variant > .5 ? '#598f4b' : '#94b963'; ctx.fillRect(d.x * T + 5, d.y * T + 8, 2, 4); ctx.fillRect(d.x * T + 9, d.y * T + 6, 2, 5); }
      else if (hash(d.x + 212, d.y) > .45) drawFlower(d.x + .26, d.y + .2, d.variant > .5 ? '#f5df9a' : '#f5d2d7', .8);
    }
    for (const [k, type] of obstacles) { const [x, y] = k.split(',').map(Number); if (x >= minX - 1 && x <= maxX + 1 && y >= minY - 1 && y <= maxY + 1) drawTree(x, y, type); }
    for (const f of flowers) if (!f.found && f.x >= minX - 1 && f.x <= maxX + 1 && f.y >= minY - 1 && f.y <= maxY + 1) drawFlower(f.x, f.y, f.color, 1, true);
    if (mira.x >= minX - 1 && mira.x <= maxX + 1 && mira.y >= minY - 1 && mira.y <= maxY + 1) drawMira();
    drawPlayer(); ctx.restore();
  }
  function blocked(x, y) {
    if (x < 1 || y < 1 || x > WORLD - 2 || y > WORLD - 2) return true;
    const tx = Math.floor(x), ty = Math.floor(y);
    for (let oy = -1; oy <= 1; oy++) for (let ox = -1; ox <= 1; ox++) {
      const type = obstacles.get(keyOf(tx + ox, ty + oy));
      if (type && type !== 'bush' && Math.hypot(x - (tx + ox + .5), y - (ty + oy + .55)) < .68) return true;
      if (type === 'bush' && Math.hypot(x - (tx + ox + .5), y - (ty + oy + .5)) < .42) return true;
    }
    return false;
  }
  function inputAxis() {
    const up = keys.has('ArrowUp') || keys.has('w') || touchDirs.has('up');
    const down = keys.has('ArrowDown') || keys.has('s') || touchDirs.has('down');
    const left = keys.has('ArrowLeft') || keys.has('a') || touchDirs.has('left');
    const right = keys.has('ArrowRight') || keys.has('d') || touchDirs.has('right');
    return { x: (right ? 1 : 0) - (left ? 1 : 0), y: (down ? 1 : 0) - (up ? 1 : 0) };
  }
